template_path = "devotional-template.html"

if not os.path.exists(template_path):
    print("Error: Could not find 'devotional-template.html' in this directory.")
    exit()

with open(template_path, "r", encoding="utf-8") as f:
    template = f.read()

print(f"Starting execution loop for {len(devotionals)} August standalone pages...")

for item in devotionals:
    day = item["day"]
    body_html = "".join([f"<p>{p}</p>" for p in item["body"]])
    
    # Matching original July navigation structure: day1.html, day2.html...
    prev_link = f"day{day-1}.html" if day > 1 else "../2026July/day31.html"
    next_link = f"day{day+1}.html" if day < len(devotionals) else "#"
    
    output = template
    output = output.replace("{{DAY}}", str(day))
    output = output.replace("{{TITLE}}", item["title"])
    output = output.replace("{{OPENING}}", item["opening"])
    output = output.replace("{{BODY}}", body_html)
    output = output.replace("{{MEM_VERSE}}", item["memVerse"])
    output = output.replace("{{MEM_REF}}", item["memRef"])
    output = output.replace("{{PRAYER}}", item["prayer"])
    output = output.replace("{{PREV_LINK}}", prev_link)
    output = output.replace("{{NEXT_LINK}}", next_link)
    
    # Output directly inside 2026August
    file_path = f"day{day}.html"
    with open(file_path, "w", encoding="utf-8") as out_f:
        out_f.write(output)
    print(f" ✓ Generated successfully: {file_path}")

print("\nAll 31 August devotional subpages built perfectly in 2026August!")